//La clase ABSTRACTA de Modulo. En base a este haré lols demás
public abstract class Modulo {

    protected String id;
    protected String nombre;
    protected int salud;
    protected boolean activo;
    protected int clase;
    protected float costo;


//Constructor vácio o "Default"
    public Modulo() {
        id = "";
        nombre = "";
        salud = 0;
        activo = false;
        clase = 0;
        costo = 0;
    }

//Constructor con los atributos ua definitdos.
    public Modulo(String id, String nombre, int salud, boolean activo, int clase, float costo) {
        this.id = id;
        this.nombre = nombre;
        this.salud = salud;
        this.activo = activo;
        this.clase = clase;
        this.costo = costo;
    }

//Setters y Getters
    public void setId(String newId) {
        id = newId;
    }

    public String getId() {
        return id;
    }


    public void setNombre(String newNombre) {
        nombre = newNombre;
    }

    public String getNombre() {
        return nombre;
    }


    public void setSalud(int newSalud) {
        salud = newSalud;
    }

    public int getSalud() {
        return salud;
    }


    public void setActivo(boolean newActivo) {
        activo = newActivo;
    }

    public boolean getActivo() {
        return activo;
    }


    public void setClase(int newClase) {
        clase = newClase;
    }

    public int getClase() {
        return clase;
    }


    public void setCosto(float newCosto) {
        costo = newCosto;
    }

    public float getCosto() {
        return costo;
    }

//El proceso es abstracto. Luego haré un Override en los siguientes Modulos para que este proceso sea exclusiva,
//  basado en que cada uno tiene su propia cosa exclusiva


    public abstract void procesoCiclo(Mision mision);

//Este tambien, pero haré luego un override para agregar los datos exclusivos
    public abstract void mostrarCaracteristicas();

//Override al nuevo toString
    @Override
    public String toString() {
        return "ID: " + id + "\nNombre: " + nombre + "\nSalud: " + salud + "%" + "\nActivo: " + activo + "\nCosto: Q" + costo;
    }
}